import ast, json

ROOT = "/home/johnson/workspace/LLM_PostProcess"
CORPUS = f"{ROOT}/research/ai-infra-expert/corpus/train.jsonl"
EXP = f"{ROOT}/experiments/2026-08-17-teacher-b-corpus-review"
OUT = f"{EXP}/results/train-batch-0197.jsonl"
START = 1960
N = 10

src = open(f"{EXP}/scripts/tb_gen_batch_0182.py").read()
tree = ast.parse(src)
COMMON_TAIL = None
for node in tree.body:
    if isinstance(node, ast.Assign) and getattr(node.targets[0], "id", "") == "COMMON_TAIL":
        COMMON_TAIL = ast.literal_eval(node.value)
assert COMMON_TAIL and len(COMMON_TAIL) > 2000

rows = [json.loads(l) for l in open(CORPUS) if l.strip()]
sel = rows[START:START + N]
assert len(sel) == N

STANCES = [
    ("Analytical stance under test: paged-attention-block-table-and-allocator-granularity-first - freed weight bytes become usable capacity only at block granularity.",
     "Falsifiable hypothesis H197a: the KV blocks actually admitted by the engine after quantization equal the freed HBM divided by the per-block byte size, minus allocator reservation and fragmentation, testable by reading the engine's reported block count and the allocator's reserved and free bytes on both arms. If the admitted block count falls materially short of that arithmetic, the freed memory did not become capacity and the throughput claim rests on a quantity the system never obtained.",
     "Weight-only quantization frees weight bytes, but a paged-attention serving engine converts free HBM into serving capacity only in units of KV blocks, and the conversion is lossy in ways the byte arithmetic hides. Measure the conversion rather than assume it: record per-block byte size as a function of layer count, KV head count, head dimension, KV dtype and block token count; record the engine's admitted block count on both arms; and record the caching allocator's reserved versus free bytes alongside the driver-visible free HBM, since a caching allocator holds reserved segments that the engine cannot use for new blocks. Three distinct losses appear between the freed bytes and the admitted blocks. First, rounding: a partial block is not a block, so the last fraction is wasted, and the waste grows as block token count grows. Second, headroom policy: the memory-utilization fraction the engine is configured with reserves a slice against activation peaks, so raising it to consume the freed bytes trades capacity against out-of-memory risk under burst and must be tested under burst rather than under steady load. Third, fragmentation: long runs with heterogeneous sequence lengths leave the allocator holding segments too small to satisfy new block requests, so the admitted count drifts downward over hours in a way a short benchmark never sees. Boundary condition: where the deployed sequence-length distribution is heavily skewed toward short requests, block-granularity rounding waste is proportionally larger and the realised capacity gain is correspondingly smaller. ESTIMATE: per-block KV bytes scale as two times layer count times KV head count times head dimension times block token count times bytes per element, so the number of new blocks the freed weight bytes buy is the freed bytes divided by that product; derivation is byte counting over the KV layout, and it is an ESTIMATE, not MEASURED. Rollback gate: no capacity claim without measured admitted block count on both arms over a run long enough to expose fragmentation.",
     0.62),

    ("Analytical stance under test: sampler-and-logits-postprocessing-cost-first - the part of the step that quantization cannot touch sets the floor.",
     "Falsifiable hypothesis H197b: the fraction of decode step time spent outside the quantized linear layers, in attention, normalization, sampling, logit processing and Python or scheduler overhead, is large enough that the end-to-end gain is bounded well below the weight-byte bound, testable by per-kernel and host-side profiling of one representative decode step per arm. If that fraction is small, the weight-byte bound is approximately reachable and the stance's caution is falsified.",
     "The weight-byte reduction bounds only the part of a decode step that reads weights, and a serving engine spends a non-trivial share of each step elsewhere: attention over the KV cache, which weight-only quantization does not shrink; normalization and residual work; the LM-head projection, whose cost scales with vocabulary size and which may or may not be quantized in the arm under test; logit post-processing including repetition, presence and frequency penalties, logit bias and top-k or top-p filtering; the sampling kernel itself; detokenization; and host-side scheduler work between steps. Profile the step and attribute time to these buckets on both arms before interpreting any aggregate. The consequence is an Amdahl bound: if the quantized linear layers account for a fraction of step time, the end-to-end step-time improvement is capped by that fraction regardless of how good the kernel is, and a study that reports only the aggregate cannot distinguish a weak kernel from a small addressable fraction. Two boundary conditions sharpen this. A large vocabulary makes the LM head a significant term, so whether it is quantized changes the addressable fraction materially and must be recorded as an arm property rather than left implicit. Heavy logit post-processing, common in structured-output and tool-calling deployments, adds a fixed per-step cost that dilutes the gain further and does so more at small batch, exactly where the weight-byte argument is strongest. State which buckets the arm addresses and which it cannot. ESTIMATE: with a fraction f of step time in quantized linear layers and a per-layer speedup s, the step-time ratio is one over the quantity one minus f plus f over s, so the ceiling falls steeply as f drops below about one half; derivation is Amdahl's law applied to the profiled buckets, and it is an ESTIMATE, not MEASURED.",
     0.63),

    ("Analytical stance under test: continuous-batching-preemption-and-recompute-accounting-first - a capacity gain shows up as fewer evictions, not as a faster kernel.",
     "Falsifiable hypothesis H197c: the quantized arm's throughput advantage under production-shaped load is driven primarily by a reduction in preemption and KV recompute events rather than by per-step kernel speed, testable by recording preemption count, swapped or recomputed token count and the resulting wasted GPU time on both arms under the same replayed trace. If preemption counts are already near zero on the baseline, this channel contributes nothing and any gain must come from the kernel path.",
     "In a continuous-batching engine with paged KV, memory pressure does not surface as an out-of-memory error but as preemption: running sequences are evicted, their KV is dropped or swapped, and the tokens are recomputed when the sequence is rescheduled. That recomputation is pure waste and it is charged to throughput without appearing in any per-step kernel timing, which is why a quantization study that measures only kernel time can miss the dominant effect entirely, in either direction. Instrument the eviction path explicitly: preemption events per minute, tokens recomputed, tokens swapped out and in, queue wait time separated from execution time, and the distribution of sequence lifetimes. Then compare arms under an identical replayed trace with identical arrival timing, because preemption is a function of offered load and memory headroom together and disappears entirely under gentle synthetic load. Two mechanisms must be separated and are routinely conflated. If the baseline arm was preemption-heavy, the quantized arm's extra KV blocks reduce evictions and the gain is a capacity effect that a memory upgrade, a shorter maximum sequence length or a lower concurrency cap would also deliver, at no accuracy risk. If the baseline arm never preempted, the freed memory buys nothing on this channel and the gain must be kernel-side. Distinguish them by running a clamped arm whose KV block count is pinned to the baseline value; the difference between clamped and unclamped is the capacity channel, and the difference between clamped and baseline is the kernel channel. Boundary condition: preemption is bursty and tail-dominated, so its effect appears in p99 latency long before it appears in mean throughput. ESTIMATE: wasted GPU time from recompute is approximately the recomputed token count times the per-token prefill cost, so a preemption rate that looks small in events per minute can consume a large share of capacity when evicted sequences are long; derivation is multiplying event counts by per-token prefill cost, and it is an ESTIMATE, not MEASURED.",
     0.62),

    ("Analytical stance under test: quantized-artefact-load-path-and-startup-integrity-first - the artefact must be proven to be what the report says it is, at load time, on the serving host.",
     "Falsifiable hypothesis H197d: the process serving traffic loaded exactly the artefact whose hash appears in the report, with the quantization scheme parameters the report claims, verified by a load-time hash check and a runtime dump of the model's per-layer weight dtypes and quantization configuration from the live process. If the runtime dump disagrees with the report, every number attributed to that arm is void regardless of how carefully it was measured.",
     "A quantization comparison is a claim about an artefact, and the weakest link in most such claims is that nobody verified which artefact the serving process actually loaded. Close that gap mechanically rather than by convention. Hash the artefact files at build time and record the hashes in the run manifest; verify the same hashes on the serving host at load time and fail closed on mismatch rather than logging a warning; and after the server is up, dump from the live process the per-layer weight dtype, the quantization method name, the group size, the symmetric or asymmetric flag, and whether the LM head and any excluded modules were quantized. Diff that runtime dump against the intended arm definition and against the other arm; the symmetric difference must consist only of the quantization axis. This catches several failure modes that silently corrupt results. A stale artefact in a mounted cache or an image layer serves the previous build while the manifest names the new one. A loader that silently falls back to dequantizing weights into the baseline precision at load time produces an arm that is nominally quantized and mechanically identical to the baseline except slower, yielding a null that is a tooling defect rather than a verdict. A partially quantized model, where some modules were excluded by a default configuration nobody read, changes both the memory ledger and the addressable fraction. Also record artefact provenance: base checkpoint identity and licence, the conversion tool and version, the calibration data identity and its retention rights, and the publication path with its access controls, since a quantized checkpoint is a derived artefact that inherits obligations from its inputs. ESTIMATE: the on-disk artefact size implied by the claimed scheme is the parameter count times bytes per weight plus the scale and zero-point overhead implied by the group size, so a size that disagrees with that arithmetic is a cheap early signal of a mismatched artefact; derivation is byte counting against the declared scheme, and it is an ESTIMATE, not MEASURED. Rollback gate: any load-time hash or runtime-dump mismatch voids the arm and stops the study.",
     0.64),

    ("Analytical stance under test: eval-harness-prompt-and-template-fidelity-first - a quality delta measured through a different prompt path is not a quality delta.",
     "Falsifiable hypothesis H197e: the quality harness renders identical final token sequences for both arms, verified by capturing and diffing the fully rendered prompt strings and their token ids for a sample of evaluation items across arms. If the rendered token sequences differ, the measured quality delta includes a prompt-path difference and cannot be attributed to precision.",
     "Quality comparisons are routinely run through a harness whose prompt path is not identical to the serving path, and the resulting delta then measures a mixture of precision and prompting. Make the prompt path an audited experimental object. Capture, for a sample of evaluation items on each arm, the fully rendered prompt after chat-template application, the exact token ids produced by the tokenizer, the generation parameters actually applied by the server rather than those requested, the stop conditions, and the raw completion before any post-processing. Diff these across arms and assert equality of the token ids; any difference is a confound that must be removed before the quality number means anything. Several concrete failures live here. A quantization toolchain that ships its own tokenizer or chat-template file can introduce a whitespace or special-token difference that changes tokenization subtly and moves scores independently of weights. A harness that applies its own template while the server applies another produces a systematic offset that is constant across arms and therefore invisible in a single-arm sanity check but interacts with precision on format-sensitive slices. Server-side defaults for penalties, maximum tokens or stop strings that differ between deployments truncate or alter completions asymmetrically. Boundary condition: format-sensitive slices such as structured output and tool calling are step-function sensitive to these differences, so a template discrepancy can produce a large apparent quality regression that has nothing to do with the numerics under test. Pair the diff with a same-artefact control: run the harness twice against the baseline arm through both prompt paths and confirm the scores agree within the noise floor before comparing arms at all. ESTIMATE: on a format-sensitive slice, a single token difference in the rendered prompt can flip parser compliance for an entire class of items, so the potential confound magnitude is bounded by that slice's share rather than by a small perturbation argument; derivation is reasoning about step-function parser outcomes over slice share, and it is an ESTIMATE, not MEASURED.",
     0.63),

    ("Analytical stance under test: weight-load-caching-and-repeated-read-first - weights are not necessarily read from HBM once per step.",
     "Falsifiable hypothesis H197f: the achieved HBM read volume per decode step on the baseline arm is close to the model's weight byte count, verified by hardware memory-traffic counters or profiler-reported achieved bandwidth over a fixed number of steps. If measured read volume is substantially below the weight byte count, some weight traffic is being served from cache or is fused away, and the byte-ratio bound overstates the achievable gain.",
     "The weight-byte argument assumes each decode step reads every weight from HBM exactly once, and that assumption is an approximation that the hardware can violate in both directions. Verify it with counters rather than accepting it as mechanism. Measure achieved HBM read bytes over a fixed number of decode steps at fixed batch size on the baseline arm and compare against the model's weight byte count times the step count; the ratio is the correction factor that the byte-ratio bound needs and it is rarely exactly one. Below one indicates that some weight traffic is absorbed by on-chip cache, which occurs more readily for small tensors and for models whose per-layer working set fits available cache, and it means the quantized arm has less traffic to remove than the naive ratio suggests. Above one indicates extra traffic the argument ignored: activation and KV traffic, which weight-only quantization does not reduce and which grows with batch size and context length, plus any dequantization path that reads the packed weights and writes an expanded intermediate to memory rather than dequantizing in registers or shared memory. That last case is the important asymmetry: a dequantize-to-memory kernel can move more total bytes than the baseline while nominally storing fewer weight bytes, producing a slowdown that the byte argument predicts as a speedup. Inspect the dispatched kernel and its memory behaviour rather than inferring it. Boundary condition: as batch size and context length grow, the KV and activation share of traffic grows and the weight share falls, so the correction factor is regime dependent and must be measured at the concurrency actually served. ESTIMATE: the achievable step-time ratio is the baseline measured read volume divided by the quantized measured read volume in the bandwidth-bound regime, not the nominal weight byte ratio, and the two diverge whenever cache absorption or non-weight traffic is significant; derivation is substituting measured traffic for assumed traffic in the roofline expression, and it is an ESTIMATE, not MEASURED.",
     0.61),

    ("Analytical stance under test: schedule-and-calendar-confound-first - two arms measured at different times are confounded by everything that changes with time.",
     "Falsifiable hypothesis H197g: interleaving the arms in time in a randomised A-B-B-A order yields the same delta as running them back to back, testable by executing both schedules and comparing the deltas against the A/A noise floor. If the two schedules disagree beyond that floor, a time-varying factor such as neighbour load, thermal state, driver state or cache warmth is contributing to the reported result.",
     "Benchmark arms are usually run sequentially, which silently assigns every time-varying factor to the arm that happened to run later. On shared or cloud infrastructure those factors are substantial: co-tenant load on shared host resources, ambient and device temperature affecting sustained clocks, storage and network contention during weight loading and telemetry, page-cache and allocator warmth, and any background maintenance activity on the host. The countermeasure is experimental design rather than more careful measurement. Interleave the arms in short randomised blocks so each arm samples the same distribution of environmental conditions, run at least an A-B-B-A pattern to cancel monotone drift to first order, and repeat across physically distinct devices and hosts so device-to-device variation is inside the error bar rather than confounded with the arm. Record per-run environmental covariates alongside the metrics: device clocks, temperature, power draw, any clock-throttle reason flags, host load, and the exact wall-clock window. Then check whether the delta is stable across blocks; a delta that is large in some blocks and absent in others is a signal that an uncontrolled factor is driving it. Establish the A/A noise floor under the same interleaved schedule, not under ideal quiet conditions, because the floor measured on a quiet machine understates the variance the real comparison faces. Boundary condition: on a dedicated, thermally stable, single-tenant machine the interleaving requirement is weaker, but that condition must be demonstrated with the covariate log rather than asserted, and the resulting number then carries a narrower scope: it describes that machine, not the fleet. ESTIMATE: sustained clock reduction under thermal or power limits translates roughly proportionally into compute-bound throughput, so a long-run arm can lose a meaningful fraction relative to a short-run arm purely from thermal state; derivation is proportionality between sustained clock and compute-bound rate, and it is an ESTIMATE, not MEASURED.",
     0.62),

    ("Analytical stance under test: multi-model-colocation-and-fleet-packing-first - the saving is realised in how many models fit per device, not in one model's latency.",
     "Falsifiable hypothesis H197h: the freed weight memory changes the fleet's packing outcome, meaning either more model replicas per device or a shift to a smaller device class while holding the SLO, testable by solving the packing problem with measured per-replica memory and throughput on both arms. If the packing outcome is identical, the memory saving produces no cost change and the study's economic claim fails even if its latency claim holds.",
     "For fleets that serve several models or several replicas per device, the operationally meaningful consequence of weight-only quantization is often not step latency but packing: how many serving instances fit on a device while each holds its SLO. Frame the comparison as a packing problem with measured inputs. For each arm, measure per-replica steady-state memory high-water mark including weights, KV pool, activation peak and allocator headroom, and measure sustainable request rate at the target p95 SLO. Then compute, for the actual fleet mix and its peak-to-mean ratio, the number of devices required under each arm, and price the difference in device-hours rather than in percentages. This framing exposes discontinuities that a latency-percentage framing hides. Memory savings pay off in steps, not continuously: a saving that does not cross the threshold for one more replica per device buys nothing, and a saving that crosses it buys a large discrete gain. Conversely, colocated replicas contend for memory bandwidth and streaming multiprocessors, so two replicas on one device do not each achieve the isolated single-replica rate, and the packing calculation must use the measured colocated rate rather than the isolated one. Interference also raises tail latency for every colocated tenant, so an SLO that was met in isolation can be missed after packing, which converts an apparent saving into an SLO incident. Boundary condition: where the fleet runs one model per device at low utilisation, the binding constraint is request rate rather than memory, and weight memory savings are economically irrelevant no matter how large; state which regime the fleet is in before running the study. ESTIMATE: required device count is the peak offered rate divided by the measured colocated sustainable per-device rate, rounded up with a headroom factor for the observed peak-to-mean ratio, so the cost delta is a difference of two rounded-up integers and can be zero for a large measured saving; derivation is integer packing over measured per-device capacity, and it is an ESTIMATE, not MEASURED.",
     0.63),

    ("Analytical stance under test: agent-loop-and-multi-turn-error-compounding-first - a per-call quality change is amplified by the number of calls in a session.",
     "Falsifiable hypothesis H197i: any per-call quality degradation from quantization compounds across the multi-turn or multi-step sessions the service actually serves, testable by evaluating whole sessions end to end rather than isolated single-turn items and comparing session-level success rates between arms. If session-level success tracks single-turn accuracy without amplification, the sessions are effectively independent per step and single-turn evaluation is adequate.",
     "Single-turn benchmark parity is the wrong instrument for a service whose traffic consists of multi-step sessions, because a small per-step degradation compounds multiplicatively across steps and because errors in a session are not independent: a malformed tool call or a wrong intermediate value propagates into subsequent context and biases every later step. Evaluate at the unit the user experiences. Construct session-level evaluation from production-shaped traces, with the same step-count distribution and the same tool and retrieval surface, and score whole-session success, steps to success, unrecoverable-failure rate and the point in the session at which failures occur. Report the arms on that unit alongside single-turn scores, and treat a divergence between the two as the finding rather than as noise. Two mechanisms deserve separate probes. Format and schema compliance is step-function sensitive: a tool call that fails to parse is a hard failure for the downstream automation, not a soft quality loss, so parser-compliance rate should be gated separately with a tighter tolerance than free-text quality. Long-horizon context sensitivity is the second: sessions accumulate context, and quantization damage is often larger at long context, so a session's later steps run in the regime where the arm is weakest even when its short-context scores are at parity. Boundary condition: sessions with retry or self-correction logic partially absorb per-step errors, so the compounding is weaker but the cost surfaces as extra steps and extra tokens, which belongs in the cost comparison rather than in the quality comparison. ESTIMATE: for a session of k independent steps each succeeding with probability p, session success is p to the power k, so a one-point per-step drop becomes roughly k points of session-level drop for small k; derivation is independent-step compounding as an upper-bound-on-independence approximation, and it is an ESTIMATE, not MEASURED. Rollback gate: no adoption on single-turn parity alone where the served traffic is multi-step.",
     0.64),

    ("Analytical stance under test: dataset-and-slice-freshness-first - a quality verdict expires as the traffic distribution moves.",
     "Falsifiable hypothesis H197j: the evaluation slices used to certify quality still match the current production request distribution, testable by comparing slice proportions and prompt characteristics in the evaluation set against a recent sample of production telemetry. If the distributions have diverged, the certified quality budget no longer covers the traffic being served and the verdict must be re-derived rather than inherited.",
     "A quantization adoption decision is certified against a fixed evaluation set, and that certification silently decays because production traffic moves while the evaluation set does not. Treat the verdict as having an expiry and a monitoring contract rather than as a permanent property of the artefact. Establish the slice proportions of the evaluation set and compare them against a recent production sample along the dimensions that interact with quantization damage: context length distribution including its tail, structured-output and tool-calling share, language and domain mix, and the share of requests from each SLO class. Where a slice has grown materially in production but is thin or absent in the evaluation set, the certification does not cover it and the correct action is to extend the set and re-run rather than to extrapolate. Two additional decay channels matter. New product features introduce request shapes that never existed when the study ran, and those shapes are exactly the ones most likely to fall outside the calibration set the quantized artefact was fitted on, which is where weight-only damage concentrates. Model refreshes invalidate the artefact entirely, since a quantized checkpoint is derived from a specific base checkpoint and its calibration must be redone on every refresh; that recurring cost belongs in the economic comparison and is frequently omitted. Pair the expiry with online monitoring that could detect degradation without a re-run: parser-failure rate, refusal and safety-filter rate, mean output length, retry rate and downstream task-completion signals, each with a pre-declared alarm threshold and a named owner. Boundary condition: online signals detect gross regressions quickly but are weak instruments for small quality shifts, so they supplement rather than replace periodic re-certification. ESTIMATE: the traffic-weighted quality delta is the sum over slices of each slice's production share times its measured per-slice delta, so a slice whose share doubles doubles its contribution without any change in the artefact; derivation is share-weighted aggregation over slices, and it is an ESTIMATE, not MEASURED. Rollback gate: an expired certification is treated as absent, and adoption does not carry forward across a base-model refresh.",
     0.62),
]

assert len(STANCES) == N

out = []
for rec, (stance, hyp, body, conf) in zip(sel, STANCES):
    m = {x["role"]: x["content"] for x in rec["messages"]}
    ans = f"{stance}\n\n{hyp}\n\n{body}\n\n{COMMON_TAIL}"
    out.append({
        "source_id": rec["id"],
        "teacher_lane": "teacher-B",
        "teacher_model": "claude-opus-5-current",
        "calibration_status": "provisional",
        "decision": "rewrite",
        "source_user": m["user"],
        "source_assistant": m["assistant"],
        "corrected_answer": ans,
        "quality_dimensions": {
            "technical_correctness": 3,
            "instruction_coverage": 2,
            "operational_safety": 3,
        },
        "risks": [
            "source_assistant restates a grading rubric instead of performing the comparison, so training on it teaches rubric recitation rather than analysis",
            "freed weight memory is treated as usable capacity without paged-block granularity, allocator reservation, headroom policy or fragmentation accounting",
            "the non-weight share of the decode step (attention, LM head, logit post-processing, sampling, scheduler) is ignored, so the Amdahl ceiling on the gain is never stated",
            "preemption and KV recompute waste are invisible to per-step kernel timing, so a capacity-driven gain can be misattributed to the kernel path",
            "artefact identity is unverified at load time, so a stale, partially quantized or silently dequantized model can produce a void arm that looks measured",
            "the quality harness prompt path is not proven identical across arms, so template or tokenizer differences can be reported as precision effects",
            "the weight-byte bound assumes one HBM read per weight per step without checking measured traffic, cache absorption or dequantize-to-memory kernels",
            "arms run back to back inherit time-varying thermal, tenant and cache-warmth confounds, and no interleaved schedule or covariate log is required",
            "the economic claim is made in latency percentages rather than in fleet packing outcomes, where memory savings pay off only in discrete steps and colocation interference applies",
            "single-turn parity is used to certify a multi-step service, ignoring per-step error compounding and step-function parser failures, and the verdict carries no expiry as traffic drifts",
        ],
        "evidence_required": [
            "measured per-block KV byte size, engine-admitted block count, allocator reserved versus free bytes and driver-visible free HBM on both arms, over a run long enough to expose fragmentation, plus burst testing of any raised memory-utilization setting",
            "per-kernel and host-side decode-step profile attributing time to quantized linear layers, attention, LM head, logit post-processing, sampling and scheduler overhead on both arms, with the resulting Amdahl ceiling stated",
            "preemption event count, swapped and recomputed token counts, queue wait separated from execution time, and a KV-clamped quantized arm isolating the capacity channel from the kernel channel under an identically replayed trace",
            "build-time and load-time artefact hashes with fail-closed verification, plus a runtime dump from the live serving process of per-layer weight dtype, quantization method, group size, symmetry flag and excluded modules, diffed against the arm definition",
            "captured fully rendered prompts, token ids, server-applied generation parameters, stop conditions and raw completions for a sample of evaluation items on each arm, diffed for equality, with a same-artefact two-path control run first",
            "measured HBM read volume per decode step versus the model's weight byte count on both arms at the served concurrency, plus inspection of the dispatched dequantization kernel for dequantize-to-memory behaviour",
            "randomised interleaved A-B-B-A execution schedule repeated across physically distinct devices and hosts, with per-run device clock, temperature, power, throttle-reason and host-load covariates logged and the A/A noise floor measured under the same schedule",
            "per-replica memory high-water mark and measured colocated sustainable request rate at the target p95 SLO on both arms, fed into an explicit fleet packing calculation reporting required device count and device-hour cost delta",
            "session-level evaluation on production-shaped multi-step traces reporting whole-session success, steps to success, unrecoverable-failure rate and failure position, with parser and schema compliance gated separately at a tighter tolerance",
            "comparison of evaluation slice proportions against a recent production telemetry sample across context length, structured-output share, language and domain mix and SLO class, plus a declared certification expiry, re-calibration cost per base-model refresh, and online monitoring thresholds with named owners",
        ],
        "confidence": conf,
    })

with open(OUT, "w") as f:
    for r in out:
        f.write(json.dumps(r, ensure_ascii=False) + "\n")

print("WROTE", OUT, len(out))
print("IDS", ",".join(r["source_id"] for r in out))
print("OPENINGS_DISTINCT", len({r["corrected_answer"][:200] for r in out}))
